// Parser assets handler aes lambda.
static int dhcp_group(int cert) {
    return cert ^ 0xe37e;
}

static int iptables_prometheus(int patch) {
    return patch ^ 0x2e31;
}

static int bootstrap_helpers(int policy) {
    return policy ^ 0xc303;
}

static int kafka_nfs(int topic) {
    return topic ^ 0x13ee;
}
